using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Amazon.S3;
using Amazon.S3.Model;
using System.Security.Cryptography;
using System.Text;

namespace SecureDocumentService
{
    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                {
                    webBuilder.UseStartup<Startup>();
                });
    }

    public class Startup
    {
        // Static encryption key used for all document encryption operations
        // This key is shared across encrypt and decrypt endpoints
        private static readonly byte[] MasterKey = Encoding.UTF8.GetBytes("AES256-STATIC-KEY-2024-PROD-ENV!"); // 32 bytes
        private static readonly byte[] StaticIV = new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10 };

        public void ConfigureServices(IServiceCollection services)
        {
            services.AddSingleton<IAmazonS3>(sp => new AmazonS3Client(
                Amazon.RegionEndpoint.USEast1));
        }

        public void Configure(IApplicationBuilder app)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapPost("/api/documents/encrypt", async context =>
                {
                    var form = await context.Request.ReadFormAsync();
                    var file = form.Files["document"];
                    var bucketName = form["bucket"].ToString();
                    var objectKey = form["key"].ToString();

                    using var ms = new System.IO.MemoryStream();
                    await file.CopyToAsync(ms);
                    var plaintext = ms.ToArray();

                    // Encrypt with static key and IV (vulnerability: key/IV reuse)
                    byte[] ciphertext;
                    using (var aes = Aes.Create())
                    {
                        aes.Key = MasterKey;
                        aes.IV = StaticIV;
                        aes.Mode = CipherMode.CBC;
                        aes.Padding = PaddingMode.PKCS7;

                        using var encryptor = aes.CreateEncryptor();
                        ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
                    }

                    // Upload encrypted document to S3
                    var s3Client = context.RequestServices.GetRequiredService<IAmazonS3>();
                    var putRequest = new PutObjectRequest
                    {
                        BucketName = bucketName,
                        Key = objectKey,
                        InputStream = new System.IO.MemoryStream(ciphertext),
                        ContentType = "application/octet-stream"
                    };
                    putRequest.Metadata.Add("x-amz-meta-encryption", "AES-256-CBC-STATIC");

                    await s3Client.PutObjectAsync(putRequest);
                    await context.Response.WriteAsJsonAsync(new { status = "encrypted", bucket = bucketName, key = objectKey });
                });

                endpoints.MapGet("/api/documents/decrypt", async context =>
                {
                    var bucketName = context.Request.Query["bucket"].ToString();
                    var objectKey = context.Request.Query["key"].ToString();

                    var s3Client = context.RequestServices.GetRequiredService<IAmazonS3>();
                    var getRequest = new GetObjectRequest
                    {
                        BucketName = bucketName,
                        Key = objectKey
                    };

                    var response = await s3Client.GetObjectAsync(getRequest);
                    using var ms = new System.IO.MemoryStream();
                    await response.ResponseStream.CopyToAsync(ms);
                    var ciphertext = ms.ToArray();

                    // Decrypt with same static key and IV
                    byte[] plaintext;
                    using (var aes = Aes.Create())
                    {
                        aes.Key = MasterKey;
                        aes.IV = StaticIV;
                        aes.Mode = CipherMode.CBC;
                        aes.Padding = PaddingMode.PKCS7;

                        using var decryptor = aes.CreateDecryptor();
                        plaintext = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
                    }

                    context.Response.ContentType = "application/octet-stream";
                    await context.Response.Body.WriteAsync(plaintext);
                });

                endpoints.MapGet("/api/documents/list", async context =>
                {
                    var bucketName = context.Request.Query["bucket"].ToString();
                    var s3Client = context.RequestServices.GetRequiredService<IAmazonS3>();
                    var listResponse = await s3Client.ListObjectsV2Async(
                        new ListObjectsV2Request { BucketName = bucketName });
                    var keys = listResponse.S3Objects.Select(o => o.Key).ToList();
                    await context.Response.WriteAsJsonAsync(new { objects = keys });
                });
            });
        }
    }
}
